const icon=(name,size='')=>`<svg class="icon ${size}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.info}</svg>`;
const esc=(v)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=esc,trim=s=>(s||'').trim(),nKey=(p,d,n)=>[p,d,n].map(x=>String(x).normalize('NFKC').trim().toLocaleLowerCase('tr-TR')).join('|');
const nl=(s=0)=>new Date(Date.now()+s*86400000).toISOString().slice(0,10);
const TR=new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'});
const DATE=new Intl.DateTimeFormat('tr-TR',{day:'numeric',month:'short',timeZone:'UTC'});
const fmt=d=>d?TR.format(new Date(String(d).slice(0,10)+'T12:00:00Z')):'';
const fmtShort=d=>d?DATE.format(new Date(String(d).slice(0,10)+'T12:00:00Z')):'';
const dateValue=d=>d instanceof Date?d.toISOString().slice(0,10):d?String(d).slice(0,10):'';
const eventStart=p=>dateValue(p.event_at);
const eventEnd=p=>dateValue(p.event_end_at)||eventStart(p);
const eventIncludesDay=(p,day)=>Boolean(eventStart(p)&&day>=eventStart(p)&&day<=eventEnd(p));
const eventRangesOverlap=(start1,end1,start2,end2)=>Boolean(start1&&start2&&start1<=end2&&start2<=end1);
const eventRangeLabel=p=>{const start=eventStart(p),end=eventEnd(p);return !start?'':start===end?fmt(start):`${fmt(start)} – ${fmt(end)}`};
const eventScheduleLabel=p=>`${eventRangeLabel(p)}${p.event_at?' • '+String(p.event_at).slice(11,16):''}`;
// Düğün törenleri ve aileler. Tüm kişisel bilgiler isteğe bağlıdır.
const weddingStages=[['kina','Kına Gecesi'],['gelin_alma','Gelin Alma'],['balo','Düğün / Balo']];
const weddingFamily=[['bride_name','Gelin Adı Soyadı'],['groom_name','Damat Adı Soyadı'],['bride_mother','Gelinin Annesi'],['bride_father','Gelinin Babası'],['groom_mother','Damadın Annesi'],['groom_father','Damadın Babası']];
const weddingData=p=>p?.wedding_details&&typeof p.wedding_details==='object'?p.wedding_details:{};
const weddingStageDates=details=>weddingStages.map(([k])=>details?.ceremonies?.[k]?.date||'').filter(Boolean);
function getEventFormRange(form){
 const date=form.elements.date?.value||'',endDate=form.elements.end_date?.value||date;
 const category=form.elements.category?.value||'';
 const stageDates=category==='Düğün'?weddingStages.map(([k])=>form.elements[k+'_date']?.value||'').filter(Boolean):[];
 const all=[date,endDate,...stageDates].filter(Boolean).sort();
 return {start:all[0]||date,end:all[all.length-1]||endDate,baseStart:date,baseEnd:endDate};
}
function weddingExtraForm(details,show){
 const wd=details||{},ceremonies=wd.ceremonies||{};
 const family=weddingFamily.map(([key,label])=>`<div class="field"><label for="wd-${key}">${esc(label)} <small>(isteğe bağlı)</small></label><input id="wd-${key}" type="text" name="${key}" maxlength="120" value="${attr(wd[key]||'')}" placeholder="${attr(label)}"></div>`).join('');
 const schedule=weddingStages.map(([key,label])=>{const item=ceremonies[key]||{};return `<div class="wedding-stage"><h4>${esc(label)}</h4><div class="two-col">${fld(label+' Tarihi',key+'_date','','date',item.date||'')}${fld('Başlangıç Saati',key+'_time','','time',item.time||'')}</div>${fld('Yer / Konum',key+'_venue','Salon / sokak / mahalle meydanı','text',item.venue||'')}</div>`}).join('');
 return `<section id="weddingFields" class="wedding-section" ${show?'':'hidden'}><div class="wedding-title"><h3>💍 Düğün Programı ve Aile Bilgileri</h3><p>Gelin alma, kına ve balo için ayrı tarih, saat ve yer girin. Boş bıraktığınız programlar yayınlanmaz.</p></div><h4>Gelin ve Damat Aileleri</h4><div class="two-col">${family}</div><label class="inline-check"><input type="checkbox" name="weddingConsent" ${wd.family_consent?'checked':''}> <span>Girdiğim gelin, damat ve aile isimlerini paylaşmaya yetkili olduğumu ve ilgili kişilerin kamuya açık paylaşımına izin verdiğini beyan ediyorum.</span></label><h4>Tören Tarihleri ve Saatleri</h4><p class="field-hint">Tören tarihleri genel düğün aralığının dışında kalırsa takvim aralığı otomatik genişletilir.</p>${schedule}<div id="weddingRangeInfo" class="field-hint" aria-live="polite"></div></section>`;
}
function weddingDetailHtml(p){
 if(p.kind!=='event'||p.category!=='Düğün')return '';
 const wd=weddingData(p),family=weddingFamily.filter(([k])=>String(wd[k]||'').trim());
 const details=family.length?`<div class="wedding-detail-panel"><h3>Gelin, Damat ve Aileler</h3><div class="wedding-family-grid">${family.map(([k,label])=>`<div><span>${esc(label)}</span><strong>${esc(wd[k])}</strong></div>`).join('')}</div></div>`:'';
 const stages=weddingStages.filter(([k])=>wd.ceremonies?.[k]?.date).map(([k,label])=>{const s=wd.ceremonies[k];return `<div class="wedding-program-card"><strong>${esc(label)}</strong><div>${icon('calendar','sm')} ${esc(fmt(s.date))}${s.time?' • '+esc(s.time):''}</div>${s.venue?`<div>${icon('pin','sm')} ${esc(s.venue)}</div>`:''}</div>`});
 return `${details}${stages.length?`<div class="wedding-detail-panel"><h3>Düğün Programı</h3><div class="wedding-program-list">${stages.join('')}</div></div>`:''}`;
}

